"""Receive original report files generated by the initiating PC."""
import base64
import binascii
import hashlib
import io
import json
import os
from pathlib import Path
import re
import stat
import zipfile

from sqlalchemy.orm import Session

from erp.core.config import get_settings
from erp.core.errors import ConflictError
from erp.core.jsonutil import loads
from erp.models import Job
from erp.services.ad_desktop_snapshot import analysis_source_fingerprint

MAX_PACKED = 12 * 1024 * 1024
MAX_UNPACKED = 64 * 1024 * 1024
REQUIRED = {'DATA_AUDIT.md', 'STORE_AD_OVERVIEW.md', 'THRESHOLD_REPORT.md'}


def archive_path(job_id: str) -> Path:
    if not re.fullmatch(r'[a-f0-9]{32}', job_id):
        raise ConflictError('广告报告任务编号无效')
    return get_settings().data_dir / 'ad_reports' / f'{job_id}.zip'


def completion_summary(job: Job) -> dict:
    receipt = loads(job.external_ref, {})
    keys = ('store_id', 'report_sha256', 'report_bytes', 'file_count', 'download_path')
    if receipt.get('kind') == 'ad_report':
        return {key: receipt[key] for key in keys}
    # The existing generic completion route stores the approved result in
    # external_ref after marking a desktop job complete.
    if job.status == 'completed' and all(key in receipt for key in keys):
        return {key: receipt[key] for key in keys}
    raise ConflictError('广告报告尚未被服务器接收')


def accept_report(session: Session, job: Job, *, encoded: str, digest: str,
                  snapshot_hash: str, source_hash: str, summary: dict) -> dict:
    previous = loads(job.external_ref, {})
    if previous.get('kind') == 'ad_report':
        if previous.get('report_sha256') != digest:
            raise ConflictError('广告报告已保存不同结果')
        return completion_summary(job)
    if previous:
        raise ConflictError('广告报告任务已有其他结果')
    if (not re.fullmatch(r'[a-f0-9]{64}', digest)
            or len(encoded) > MAX_PACKED * 4 // 3 + 4):
        raise ConflictError('广告报告超过上传限制')
    try:
        packed = base64.b64decode(encoded, validate=True)
    except (ValueError, binascii.Error) as error:
        raise ConflictError('广告报告编码无效') from error
    if not packed or len(packed) > MAX_PACKED or hashlib.sha256(packed).hexdigest() != digest:
        raise ConflictError('广告报告压缩包校验失败')
    store_id = loads(job.payload_json, {}).get('store_id')
    source_dir = get_settings().data_dir / 'ad_task_snapshots'
    try:
        expected_snapshot = (source_dir / f'{job.id}.sha256').read_text(encoding='ascii').strip()
        expected_source = (source_dir / f'{job.id}.source.sha256').read_text(encoding='ascii').strip()
    except OSError as error:
        raise ConflictError('广告报告来源快照不存在') from error
    if (store_id != summary.get('store_id') or snapshot_hash != expected_snapshot
            or source_hash != expected_source or not isinstance(summary.get('files'), list)
            or summary.get('mode') != 'live_reviewed' or summary.get('executed') is not False):
        raise ConflictError('广告报告与任务来源不一致')
    if analysis_source_fingerprint(session, store_id) != expected_source:
        raise ConflictError('广告数据已变化，请重新生成报告')
    try:
        with zipfile.ZipFile(io.BytesIO(packed)) as archive:
            members = archive.infolist()
            names = sorted(item.filename for item in members)
            if (not REQUIRED.issubset(names) or len(names) > 60
                    or names != sorted(summary['files']) or len(names) != len(set(names))
                    or any(item.is_dir() or stat.S_ISLNK(item.external_attr >> 16)
                           or item.file_size > 16 * 1024 * 1024
                           or not (re.fullmatch(r'[A-Z0-9_-]+\.md', item.filename)
                                   or re.fullmatch(r'data/[a-z0-9_]+\.csv', item.filename))
                           for item in members)
                    or sum(item.file_size for item in members) > MAX_UNPACKED):
                raise ConflictError('广告报告文件清单无效')
            for item in members:
                with archive.open(item) as source:
                    if len(source.read(item.file_size + 1)) != item.file_size:
                        raise ConflictError('广告报告文件内容损坏')
    except (OSError, ValueError, zipfile.BadZipFile) as error:
        raise ConflictError('广告报告 ZIP 格式无效') from error
    target = archive_path(job.id)
    target.parent.mkdir(parents=True, exist_ok=True)
    if target.exists():
        if hashlib.sha256(target.read_bytes()).hexdigest() != digest:
            raise ConflictError('广告报告文件与已保存内容冲突')
    else:
        temporary = target.with_suffix('.partial')
        try:
            with temporary.open('xb') as output:
                output.write(packed)
            os.replace(temporary, target)
        finally:
            temporary.unlink(missing_ok=True)
    receipt = {'kind': 'ad_report', 'store_id': store_id,
               'report_sha256': digest, 'report_bytes': len(packed),
               'file_count': len(names),
               'download_path': f'/ad-optimization/reports/{job.id}/download'}
    job.external_ref = json.dumps(receipt, separators=(',', ':'))
    session.flush()
    return completion_summary(job)
